intro={
'main.py':'نقطة الدخول إلى العرض المحلي. لا تتلقى معاملات دوال ولا تقرأ بيانات بحثية مباشرة؛ تمرر التنفيذ إلى dashboard/app.py. الاستدعاء المتوقع من Streamlit موثق في رأس الملف.',
'dashboard/app.py':'واجهة Streamlit لقراءة الآثار المحفوظة. تنشئ دوال العرض عناصر واجهة وتقرأ CSV وJSON وNPZ وصوراً وتقارير محلية؛ لا تُدرّب نموذجاً أو تُجري استدلالاً حياً. يربط main الدوال الثماني بتبويباتها. أخطاء الملفات المطلوبة غير ملتقطة عموماً، باستثناء فحوص الوجود الموضحة أدناه.'}
manifest={}
for name, entries in groups.items():
    source=(root/name).read_text(encoding='utf-8').splitlines()
    out=['# شرح `'+name+'`','',intro[name],'','كل مقطع مقتبس آلياً من الملف المحدد؛ الأسطر الفارغة للفصل والتنسيق. التفسير من مراجعة المصدر ولا يمثل اختبار تشغيل للواجهة.','']
    included=[]
    for start,end,desc in entries:
        assert 1 <= start <= end <= len(source)
        assert not included or start > included[-1]
        included.extend(range(start,end+1))
        out += [f'## الأسطر {start}–{end}' if start != end else f'## السطر {start}', '', '```python', *source[start-1:end], '```', '', desc, '']
    target='main.py.md' if name=='main.py' else 'dashboard_app.py.md'
    (base/'line_by_line'/target).write_text('\n'.join(out),encoding='utf-8')
    manifest[name]={'document':'line_by_line/'+target,'ranges':[[a,b] for a,b,_ in entries],'sha256':hashlib.sha256((root/name).read_bytes()).hexdigest(),'review':'مراجعة يدوية للتفسير؛ لم يُختبر سلوك التشغيل','quote_verification':'تطابق آلي مع المصدر'}
(base/'dashboard_batch_manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8')
print('created',len(manifest))
